import { apiFetch, IDENTITY_BASE } from './api'
import { errorFromResponse } from './errors'
import { parseEventStream } from './sse'
import type { ReportRecord } from './org'

// ── AI report generation (FEATURE 1) ─────────────────────────────────────────
// One-click reports are generated by the backend engine through the coachai-report
// BullMQ queue. Enqueue here, then subscribe to the report event stream.
//   POST /api/org/:auth0Id/reports/ai        → { report_job_id, status }
//   GET  /api/org/:auth0Id/reports/ai/:id    → one-shot reconciliation
// Both are identity-bearing: they go through IDENTITY_BASE (identity proxy on
// the client, direct backend with service headers on the server).

export type AiReportJobStatus = 'queued' | 'running' | 'done' | 'failed'

export type AiReportRequest = {
  student_id?: string
  report_type: string
  period_start?: string
  period_end?: string
  title?: string
}

export type AiReportJobPoll = {
  report_job_id: string
  status: AiReportJobStatus
  report: ReportRecord | null
}

export const orgGenerateAiReport = (
  auth0Id: string,
  input: AiReportRequest,
): Promise<{ report_job_id: string; status: 'queued' }> => {
  return apiFetch<{ report_job_id: string; status: 'queued' }>(
    `${IDENTITY_BASE}/api/org/${encodeURIComponent(auth0Id)}/reports/ai`,
    { method: 'POST', body: JSON.stringify(input) },
  )
}

export const orgAiReportStatus = (
  auth0Id: string,
  reportJobId: string,
): Promise<AiReportJobPoll> => {
  return apiFetch<AiReportJobPoll>(
    `${IDENTITY_BASE}/api/org/${encodeURIComponent(auth0Id)}/reports/ai/${encodeURIComponent(reportJobId)}`,
  )
}

/** Subscribe to one report job's event stream (client-side only). */
export function subscribeAiReportEvents(
  auth0Id: string,
  reportJobId: string,
  onEvent: (event: AiReportJobPoll) => void,
  onFailure: (error: unknown) => void,
  signal: AbortSignal,
): () => void {
  const controller = new AbortController()
  const onAbort = () => controller.abort()
  signal.addEventListener('abort', onAbort, { once: true })

  void (async () => {
    try {
      const response = await fetch(
        `${IDENTITY_BASE}/api/org/${encodeURIComponent(auth0Id)}/reports/ai/${encodeURIComponent(reportJobId)}/events`,
        { signal: controller.signal, credentials: 'include' },
      )
      if (!response.ok) {
        throw errorFromResponse(response.status, await response.json().catch(() => ({})), {
          code: 'REPORT_EVENT_STREAM_UNAVAILABLE',
          message: 'Live report updates are temporarily unavailable.',
        })
      }
      if (!response.body) throw new Error('Report event stream returned no body.')
      for await (const event of parseEventStream<AiReportJobPoll>(response)) {
        if (controller.signal.aborted) return
        onEvent(event)
        if (event.status === 'done' || event.status === 'failed') return
      }
      if (!controller.signal.aborted) {
        throw new Error('Report event stream closed before a terminal status.')
      }
    } catch (error) {
      if (!controller.signal.aborted) onFailure(error)
    } finally {
      signal.removeEventListener('abort', onAbort)
    }
  })()

  return () => {
    signal.removeEventListener('abort', onAbort)
    controller.abort()
  }
}

// ── Share tokens (FEATURE 2) ─────────────────────────────────────────────────
// Coaches mint a token for an analysis; players open the public link (no login).
//   POST /api/org/:auth0Id/analyses/:jobId/share-token  (identity-bearing)
//   GET  /api/share/:token                              (public, no identity)
// The public resolve is NOT proxied through /api/service — /api/share is not an
// identity path; it must hit the backend base URL directly.

export type ShareTokenIssue = {
  token: string
  expires_at: string
  url: string
}

export type SharedAnalysis = {
  server_job_id: string
  auth0_id: string
  expires_at: string
  analysis: {
    summary_json: unknown
    display_name: string | null
    requested_at: string
    model: string
    video_ready: boolean
  }
}

export const createShareToken = (auth0Id: string, jobId: string): Promise<ShareTokenIssue> => {
  return apiFetch<ShareTokenIssue>(
    `${IDENTITY_BASE}/api/org/${encodeURIComponent(auth0Id)}/analyses/${encodeURIComponent(jobId)}/share-token`,
    { method: 'POST' },
  )
}

export const resolveShareToken = (token: string): Promise<SharedAnalysis> => {
  return apiFetch<SharedAnalysis>(
    `${process.env.NEXT_PUBLIC_API_URL}/api/share/${encodeURIComponent(token)}`,
  )
}
